from pathlib import Path
import base64

ROOT = Path.cwd()
REL = "components/portal/portal-context-panel.tsx"
path = ROOT / REL

if not path.exists():
    raise SystemExit(
        f"ERROR: Missing {REL}. Run this from the sepulchria-portal root."
    )

def dec(value):
    return base64.b64decode(value).decode("utf-8")

text = path.read_text(encoding="utf-8")

replacements = [
    (dec(""), dec(""), "Ancestry"),
    (dec(""), dec(""), "Association"),
    (dec(""), dec(""), "Order"),
]

for old, new, label in replacements:
    if old not in text:
        raise SystemExit(
            f"ERROR: Could not find the open {label} context block."
        )
    text = text.replace(old, new, 1)

marker = "function PublicCodexJumpContext({\n"
component = dec("")

if "function PublicCodexEntryNavigator(" not in text:
    if marker not in text:
        raise SystemExit(
            "ERROR: Could not find PublicCodexJumpContext insertion point."
        )
    text = text.replace(marker, component + marker, 1)

path.write_text(text, encoding="utf-8")

print("SUCCESS")
print("Open Codex entries now list all OTHER entries of the same type.")
print("Current entry is excluded.")
print("Each item opens its full entry directly.")
print("A small View All link remains at the bottom.")
print("Now run: npm run build")
